// Pick Winners
const n15 = node({ type: "n8n-nodes-base.code", version: 2, config: {
  "name": "Pick Winners",
  "parameters": {
    "mode": "runOnceForAllItems",
    "jsCode": "\nconst CFG = {\"messaging\":{\"mode\":\"twilio\",\"provider\":\"twilio\",\"twilio\":{\"accountSid\":\"AC00000000000000000000000000000000\",\"from\":\"+61491570006\",\"messagingServiceSid\":null,\"credential\":{\"id\":\"ZZExampleTwilio1\",\"name\":\"ZZ example Twilio API key\"},\"inboundAuth\":\"signature\",\"signatureVariable\":\"LITE_TWILIO_AUTH_TOKEN\",\"inboundCredential\":null,\"allowedRecipients\":[\"+61491570156\",\"+61491570157\",\"+61491570158\",\"+61491570159\",\"+61491570110\"],\"allowAllRecipients\":false}}};\nconst clean = (s) => String(s == null ? '' : s).trim();\nconst normPhone = (s) => { let d = clean(s).replace(/[^0-9+]/g, ''); if (d.startsWith('+61')) d = '0' + d.slice(3); d = d.replace(/[^0-9]/g, ''); return /^0[2-478][0-9]{8}$/.test(d) ? d : ''; };\n/** Australian national number (04xx xxx xxx) to E.164 (+614xxxxxxxx), as Twilio needs it. */\nconst toE164 = (s) => { const n = normPhone(s); return n ? '+61' + n.slice(1) : ''; };\n/** An Airtable answer, or an Error that fails the execution (n8n records it; nothing is marked done). */\nconst records = (r, step) => {\n  if (!r || r.statusCode !== 200) { const b = (r && r.body) || {}; const e = b.error || (r && r.error) || {}; throw new Error(step + ': Airtable ' + (r && r.statusCode ? 'HTTP ' + r.statusCode : 'no response') + ' ' + clean(typeof e === 'string' ? e : (e.message || e.type))); }\n  if (!r.body || !Array.isArray(r.body.records)) throw new Error(step + ': Airtable answered without a record list');\n  return r.body.records;\n};\n/** Every record of a paginated list (one item per page). An Error if a page failed or the page limit cut it short. */\nconst allRecords = (items, step) => {\n  const out = [];\n  items.forEach((i) => { records(i.json, step).forEach((r) => out.push(r)); });\n  const last = items.length ? items[items.length - 1].json : null;\n  if (last && last.body && last.body.offset) throw new Error(step + ': more than ' + out.length + ' records; the list could not be read completely');\n  return out;\n};\n\nconst p = $('Plan Review Requests').first().json;\nconst created = $('Reservation Check').first().json.created;\nconst rows = $('Find Reservations').isExecuted ? records($('Find Reservations').first().json, 'find reservations') : [];\n// A number that replied STOP is never sent to, whatever its contact records say. If this list cannot be read completely,\n// the run fails here and nothing is sent.\nconst stopped = {}; ($('Find Suppressions').isExecuted ? allRecords($('Find Suppressions').all(), 'find suppressions') : [])\n  .forEach((r) => { stopped[clean((r.fields || {}).To).replace(/^from /, '')] = (r.fields || {})['Log Ref'] || r.id; });\nconst T = CFG.messaging.mode === 'twilio' ? CFG.messaging.twilio : null;\nconst allowed = (n) => !T || T.allowAllRecipients === true || T.allowedRecipients.indexOf(n) >= 0;\nconst decisions = p.sends.map((s) => {\n  const mine = created[s.key];\n  if (!mine) throw new Error('reserve messages: no Message Log row was written for ' + s.key);\n  const first = rows.filter((r) => (r.fields || {})['Dedupe Key'] === s.key && (r.fields || {}).Status !== 'Skipped')\n    .sort((a, b) => (Date.parse(a.createdTime) - Date.parse(b.createdTime)) || (a.id < b.id ? -1 : 1))[0];\n  const d = { key: s.key, logId: mine, channel: s.channel, to: s.to, body: s.body };\n  if (first && first.id !== mine) {\n    // Two copies of one form reserve within moments of each other. A message reserved long before belongs to an earlier\n    // enquiry: this one is not sent again today, but it is not a duplicate of it either (its job is kept).\n    const me = rows.find((r) => r.id === mine);\n    const together = !me || Math.abs(Date.parse(me.createdTime) - Date.parse(first.createdTime)) <= 10 * 60000;\n    const ref = first.fields['Log Ref'] || first.id;\n    return Object.assign(d, together ? { action: 'lost', reason: 'duplicate: ' + ref + ' already handles this message' }\n      : { action: 'repeat', reason: 'not sent: ' + ref + ' already sent this message earlier today' });\n  }\n  if (stopped[clean(s.to)]) return Object.assign(d, { action: 'blocked', reason: 'not sent: this number replied STOP (' + stopped[clean(s.to)] + ')' });\n  if (T && !allowed(toE164(s.to))) return Object.assign(d, { action: 'blocked', reason: 'not sent: ' + toE164(s.to) + ' is not on the live test allowlist' });\n  return Object.assign(d, { action: 'deliver', to164: toE164(s.to) });\n});\nconst go = decisions.filter((d) => d.action === 'deliver');\nif (!go.length) return [{ json: { none: true, decisions: decisions } }];\nreturn go.map((d, i) => ({ json: Object.assign({}, d, i === 0 ? { decisions: decisions } : {}) }));"
  }
} });

